(4, 'سُورَةُ النِّسَاءِ', 'An-Nisaa', 'The Women', 'Medinan', 176, 77, 106, 30, 4, 6, 8, 11, 31, 42, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍۢ وَٰحِدَةٍۢ وَخَلَقَ …'),
(5, 'سُورَةُ المَائـِدَةِ', 'Al-Maaida', 'The Table', 'Medinan', 120, 106, 127, 22, 6, 7, 11, 13, 43, 51, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَوْفُوا۟ بِٱلْعُقُودِ ۚ أُحِلَّتْ لَكُم بَهِيمَةُ ٱلْأَنْعَٰمِ …'),
(6, 'سُورَةُ الأَنۡعَامِ', 'Al-An''aam', 'The Cattle', 'Meccan', 165, 128, 150, 23, 7, 8, 13, 15, 51, 60, 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَ ۖ …'),
(7, 'سُورَةُ الأَعۡرَافِ', 'Al-A''raaf', 'The Heights', 'Meccan', 206, 151, 176, 26, 8, 9, 16, 18, 61, 70, 'الٓمٓصٓ'),
