(10, 'سُورَةُ يُونُسَ', 'Yunus', 'Jonas', 'Meccan', 109, 208, 221, 14, 11, 11, 21, 22, 83, 88, 'الٓر ۚ تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْحَكِيمِ'),
