(16, 'سُورَةُ النَّحۡلِ', 'An-Nahl', 'The Bee', 'Meccan', 128, 267, 281, 15, 14, 14, 27, 28, 107, 112, 'أَتَىٰٓ أَمْرُ ٱللَّهِ فَلَا تَسْتَعْجِلُوهُ ۚ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ'),
