(18, 'سُورَةُ الكَهۡفِ', 'Al-Kahf', 'The Cave', 'Meccan', 110, 293, 304, 12, 15, 16, 30, 31, 117, 122, 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَنزَلَ عَلَىٰ عَبْدِهِ ٱلْكِتَٰبَ وَلَمْ يَجْعَل لَّهُۥ …'),
