(64, 'سُورَةُ التَّغَابُنِ', 'At-Taghaabun', 'Mutual Disillusion', 'Medinan', 18, 556, 557, 2, 28, 28, 56, 56, 222, 222, 'يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ لَهُ …'),
(65, 'سُورَةُ الطَّلَاقِ', 'At-Talaaq', 'Divorce', 'Medinan', 12, 558, 559, 2, 28, 28, 56, 56, 223, 223, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ ۖ …'),
(66, 'سُورَةُ التَّحۡرِيمِ', 'At-Tahrim', 'The Prohibition', 'Medinan', 12, 560, 561, 2, 28, 28, 56, 56, 224, 224, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَ ۖ تَبْتَغِى …'),
(67, 'سُورَةُ المُلۡكِ', 'Al-Mulk', 'The Sovereignty', 'Meccan', 30, 562, 564, 3, 29, 29, 57, 57, 225, 225, 'تَبَٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ'),
(68, 'سُورَةُ القَلَمِ', 'Al-Qalam', 'The Pen', 'Meccan', 52, 564, 566, 3, 29, 29, 57, 57, 226, 226, 'نٓ ۚ وَٱلْقَلَمِ وَمَا يَسْطُرُونَ'),
(69, 'سُورَةُ الحَاقَّةِ', 'Al-Haaqqa', 'The Reality', 'Meccan', 52, 566, 568, 3, 29, 29, 57, 57, 227, 227, 'ٱلْحَآقَّةُ'),
(70, 'سُورَةُ المَعَارِجِ', 'Al-Ma''aarij', 'The Ascending Stairways', 'Meccan', 44, 568, 570, 3, 29, 29, 57, 57, 227, 228, 'سَأَلَ سَآئِلٌۢ بِعَذَابٍۢ وَاقِعٍۢ'),
(71, 'سُورَةُ نُوحٍ', 'Nooh', 'Noah', 'Meccan', 28, 570, 571, 2, 29, 29, 57, 57, 228, 228, 'إِنَّآ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ …'),
(72, 'سُورَةُ الجِنِّ', 'Al-Jinn', 'The Jinn', 'Meccan', 28, 572, 573, 2, 29, 29, 58, 58, 229, 229, 'قُلْ أُوحِىَ إِلَىَّ أَنَّهُ ٱسْتَمَعَ نَفَرٌۭ مِّنَ ٱلْجِنِّ فَقَالُوٓا۟ إِنَّا …'),
(73, 'سُورَةُ المُزَّمِّلِ', 'Al-Muzzammil', 'The Enshrouded One', 'Meccan', 20, 574, 575, 2, 29, 29, 58, 58, 229, 230, 'يَٰٓأَيُّهَا ٱلْمُزَّمِّلُ'),
(74, 'سُورَةُ المُدَّثِّرِ', 'Al-Muddaththir', 'The Cloaked One', 'Meccan', 56, 575, 577, 3, 29, 29, 58, 58, 230, 230, 'يَٰٓأَيُّهَا ٱلْمُدَّثِّرُ'),
(75, 'سُورَةُ القِيَامَةِ', 'Al-Qiyaama', 'The Resurrection', 'Meccan', 40, 577, 578, 2, 29, 29, 58, 58, 231, 231, 'لَآ أُقْسِمُ بِيَوْمِ ٱلْقِيَٰمَةِ'),
(76, 'سُورَةُ الإِنسَانِ', 'Al-Insaan', 'Man', 'Medinan', 31, 578, 580, 3, 29, 29, 58, 58, 231, 232, 'هَلْ أَتَىٰ عَلَى ٱلْإِنسَٰنِ حِينٌۭ مِّنَ ٱلدَّهْرِ لَمْ يَكُن شَيْـًۭٔا …'),
(77, 'سُورَةُ المُرۡسَلَاتِ', 'Al-Mursalaat', 'The Emissaries', 'Meccan', 50, 580, 581, 2, 29, 29, 58, 58, 232, 232, 'وَٱلْمُرْسَلَٰتِ عُرْفًۭا'),
(78, 'سُورَةُ النَّبَإِ', 'An-Naba', 'The Announcement', 'Meccan', 40, 582, 583, 2, 30, 30, 59, 59, 233, 233, 'عَمَّ يَتَسَآءَلُونَ'),
(79, 'سُورَةُ النَّازِعَاتِ', 'An-Naazi''aat', 'Those who drag forth', 'Meccan', 46, 583, 584, 2, 30, 30, 59, 59, 233, 233, 'وَٱلنَّٰزِعَٰتِ غَرْقًۭا'),
(80, 'سُورَةُ عَبَسَ', 'Abasa', 'He frowned', 'Meccan', 42, 585, 585, 1, 30, 30, 59, 59, 234, 234, 'عَبَسَ وَتَوَلَّىٰٓ'),
(81, 'سُورَةُ التَّكۡوِيرِ', 'At-Takwir', 'The Overthrowing', 'Meccan', 29, 586, 586, 1, 30, 30, 59, 59, 234, 234, 'إِذَا ٱلشَّمْسُ كُوِّرَتْ'),
(82, 'سُورَةُ الانفِطَارِ', 'Al-Infitaar', 'The Cleaving', 'Meccan', 19, 587, 587, 1, 30, 30, 59, 59, 235, 235, 'إِذَا ٱلسَّمَآءُ ٱنفَطَرَتْ'),
(83, 'سُورَةُ المُطَفِّفِينَ', 'Al-Mutaffifin', 'Defrauding', 'Meccan', 36, 587, 589, 3, 30, 30, 59, 59, 235, 235, 'وَيْلٌۭ لِّلْمُطَفِّفِينَ'),
(84, 'سُورَةُ الانشِقَاقِ', 'Al-Inshiqaaq', 'The Splitting Open', 'Meccan', 25, 589, 589, 1, 30, 30, 59, 59, 236, 236, 'إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ'),
(85, 'سُورَةُ البُرُوجِ', 'Al-Burooj', 'The Constellations', 'Meccan', 22, 590, 590, 1, 30, 30, 59, 59, 236, 236, 'وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ'),
(86, 'سُورَةُ الطَّارِقِ', 'At-Taariq', 'The Morning Star', 'Meccan', 17, 591, 591, 1, 30, 30, 59, 59, 236, 236, 'وَٱلسَّمَآءِ وَٱلطَّارِقِ'),
(87, 'سُورَةُ الأَعۡلَىٰ', 'Al-A''laa', 'The Most High', 'Meccan', 19, 591, 592, 2, 30, 30, 60, 60, 237, 237, 'سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى'),
(88, 'سُورَةُ الغَاشِيَةِ', 'Al-Ghaashiya', 'The Overwhelming', 'Meccan', 26, 592, 592, 1, 30, 30, 60, 60, 237, 237, 'هَلْ أَتَىٰكَ حَدِيثُ ٱلْغَٰشِيَةِ'),
(89, 'سُورَةُ الفَجۡرِ', 'Al-Fajr', 'The Dawn', 'Meccan', 30, 593, 594, 2, 30, 30, 60, 60, 237, 237, 'وَٱلْفَجْرِ'),
(90, 'سُورَةُ البَلَدِ', 'Al-Balad', 'The City', 'Meccan', 20, 594, 594, 1, 30, 30, 60, 60, 238, 238, 'لَآ أُقْسِمُ بِهَٰذَا ٱلْبَلَدِ'),
(91, 'سُورَةُ الشَّمۡسِ', 'Ash-Shams', 'The Sun', 'Meccan', 15, 595, 595, 1, 30, 30, 60, 60, 238, 238, 'وَٱلشَّمْسِ وَضُحَىٰهَا'),
(92, 'سُورَةُ اللَّيۡلِ', 'Al-Lail', 'The Night', 'Meccan', 21, 595, 596, 2, 30, 30, 60, 60, 238, 238, 'وَٱلَّيْلِ إِذَا يَغْشَىٰ'),
(93, 'سُورَةُ الضُّحَىٰ', 'Ad-Dhuhaa', 'The Morning Hours', 'Meccan', 11, 596, 596, 1, 30, 30, 60, 60, 238, 238, 'وَٱلضُّحَىٰ'),
(94, 'سُورَةُ الشَّرۡحِ', 'Ash-Sharh', 'The Consolation', 'Meccan', 8, 596, 596, 1, 30, 30, 60, 60, 239, 239, 'أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ'),
(95, 'سُورَةُ التِّينِ', 'At-Tin', 'The Fig', 'Meccan', 8, 597, 597, 1, 30, 30, 60, 60, 239, 239, 'بِّسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلتِّينِ وَٱلزَّيْتُونِ'),
(96, 'سُورَةُ العَلَقِ', 'Al-Alaq', 'The Clot', 'Meccan', 19, 597, 597, 1, 30, 30, 60, 60, 239, 239, 'ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ'),
(97, 'سُورَةُ القَدۡرِ', 'Al-Qadr', 'The Power, Fate', 'Meccan', 5, 598, 598, 1, 30, 30, 60, 60, 239, 239, 'بِّسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ'),
(98, 'سُورَةُ البَيِّنَةِ', 'Al-Bayyina', 'The Evidence', 'Medinan', 8, 598, 599, 2, 30, 30, 60, 60, 239, 239, 'لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ …'),
(99, 'سُورَةُ الزَّلۡزَلَةِ', 'Az-Zalzala', 'The Earthquake', 'Medinan', 8, 599, 599, 1, 30, 30, 60, 60, 239, 239, 'إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا'),
(100, 'سُورَةُ العَادِيَاتِ', 'Al-Aadiyaat', 'The Chargers', 'Meccan', 11, 599, 600, 2, 30, 30, 60, 60, 239, 240, 'وَٱلْعَٰدِيَٰتِ ضَبْحًۭا'),
(101, 'سُورَةُ القَارِعَةِ', 'Al-Qaari''a', 'The Calamity', 'Meccan', 11, 600, 600, 1, 30, 30, 60, 60, 240, 240, 'ٱلْقَارِعَةُ'),
(102, 'سُورَةُ التَّكَاثُرِ', 'At-Takaathur', 'Competition', 'Meccan', 8, 600, 600, 1, 30, 30, 60, 60, 240, 240, 'أَلْهَىٰكُمُ ٱلتَّكَاثُرُ'),
(103, 'سُورَةُ العَصۡرِ', 'Al-Asr', 'The Declining Day, Epoch', 'Meccan', 3, 601, 601, 1, 30, 30, 60, 60, 240, 240, 'وَٱلْعَصْرِ'),
(104, 'سُورَةُ الهُمَزَةِ', 'Al-Humaza', 'The Traducer', 'Meccan', 9, 601, 601, 1, 30, 30, 60, 60, 240, 240, 'وَيْلٌۭ لِّكُلِّ هُمَزَةٍۢ لُّمَزَةٍ'),
(105, 'سُورَةُ الفِيلِ', 'Al-Fil', 'The Elephant', 'Meccan', 5, 601, 601, 1, 30, 30, 60, 60, 240, 240, 'أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ٱلْفِيلِ'),
(106, 'سُورَةُ قُرَيۡشٍ', 'Quraish', 'Quraysh', 'Meccan', 4, 602, 602, 1, 30, 30, 60, 60, 240, 240, 'لِإِيلَٰفِ قُرَيْشٍ'),
(107, 'سُورَةُ المَاعُونِ', 'Al-Maa''un', 'Almsgiving', 'Meccan', 7, 602, 602, 1, 30, 30, 60, 60, 240, 240, 'أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ'),
(108, 'سُورَةُ الكَوۡثَرِ', 'Al-Kawthar', 'Abundance', 'Meccan', 3, 602, 602, 1, 30, 30, 60, 60, 240, 240, 'إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ'),
(109, 'سُورَةُ الكَافِرُونَ', 'Al-Kaafiroon', 'The Disbelievers', 'Meccan', 6, 603, 603, 1, 30, 30, 60, 60, 240, 240, 'قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ'),
(110, 'سُورَةُ النَّصۡرِ', 'An-Nasr', 'Divine Support', 'Medinan', 3, 603, 603, 1, 30, 30, 60, 60, 240, 240, 'إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ'),
(111, 'سُورَةُ المَسَدِ', 'Al-Masad', 'The Palm Fibre', 'Meccan', 5, 603, 603, 1, 30, 30, 60, 60, 240, 240, 'تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ'),
(112, 'سُورَةُ الإِخۡلَاصِ', 'Al-Ikhlaas', 'Sincerity', 'Meccan', 4, 604, 604, 1, 30, 30, 60, 60, 240, 240, 'قُلْ هُوَ ٱللَّهُ أَحَدٌ'),
(113, 'سُورَةُ الفَلَقِ', 'Al-Falaq', 'The Dawn', 'Meccan', 5, 604, 604, 1, 30, 30, 60, 60, 240, 240, 'قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ'),
(114, 'سُورَةُ النَّاسِ', 'An-Naas', 'Mankind', 'Meccan', 6, 604, 604, 1, 30, 30, 60, 60, 240, 240, 'قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ');

